-- transactions: every query is scoped by user_id. delta_minor is generated by the DB (sign from type).
-- Date params named from_date/to_date are INCLUSIVE (they mirror the API's from/to).

-- name: InsertTransaction :one
INSERT INTO transactions (user_id, account_id, category_id, type, amount_minor, currency, occurred_on,
                          description, input_method, voice_transcript, transfer_id)
VALUES (@user_id, @account_id, sqlc.narg('category_id'), @type, @amount_minor, @currency, @occurred_on,
        sqlc.narg('description'), @input_method, sqlc.narg('voice_transcript'), sqlc.narg('transfer_id'))
RETURNING *;

-- name: GetTransaction :one
SELECT * FROM transactions WHERE id = @id AND user_id = @user_id;

-- name: GetTransactionForUpdate :one
SELECT * FROM transactions WHERE id = @id AND user_id = @user_id FOR UPDATE;

-- name: UpdateTransaction :one
-- Full replacement of the editable fields: the service merges the PATCH onto the locked old row
-- (GetTransactionForUpdate) and passes every value. delta_minor is recomputed by the DB.
UPDATE transactions SET
  account_id       = @account_id,
  category_id      = sqlc.narg('category_id'),
  type             = @type,
  amount_minor     = @amount_minor,
  currency         = @currency,
  occurred_on      = @occurred_on,
  description      = sqlc.narg('description'),
  input_method     = @input_method,
  voice_transcript = sqlc.narg('voice_transcript'),
  updated_at       = now()
WHERE id = @id AND user_id = @user_id
RETURNING *;

-- name: DeleteTransaction :one
-- Returns what the caller needs to reverse the balance (ApplyBalanceDelta with -delta_minor) and to find a
-- transfer's other leg. pgx.ErrNoRows = not found / not yours.
DELETE FROM transactions WHERE id = @id AND user_id = @user_id
RETURNING account_id, delta_minor, transfer_id;

-- name: DeleteTransferPeer :many
-- Deleting one transfer leg deletes the whole transfer (docs/API.md): removes the other leg(s) sharing
-- transfer_id and returns what the caller needs to reverse each balance.
DELETE FROM transactions
WHERE user_id = @user_id AND transfer_id = @transfer_id AND id <> @id
RETURNING account_id, delta_minor;

-- name: ListTransactions :many
-- Keyset page ordered occurred_on DESC, created_at DESC, id DESC. Every filter is optional (NULL = no filter).
-- Cursor: pass all three cursor_* values (the last row of the previous page) or none. Fetch row_limit = limit+1
-- to know whether a next page exists. q is matched as a literal substring (% _ \ are escaped here).
SELECT * FROM transactions
WHERE user_id = @user_id
  AND (sqlc.narg('type')::text IS NULL OR type = sqlc.narg('type')::text)
  AND (sqlc.narg('account_id')::uuid IS NULL OR account_id = sqlc.narg('account_id')::uuid)
  AND (sqlc.narg('category_id')::uuid IS NULL OR category_id = sqlc.narg('category_id')::uuid)
  AND (sqlc.narg('from_date')::date IS NULL OR occurred_on >= sqlc.narg('from_date')::date)
  AND (sqlc.narg('to_date')::date IS NULL OR occurred_on <= sqlc.narg('to_date')::date)
  AND (sqlc.narg('q')::text IS NULL OR description ILIKE
        '%' || replace(replace(replace(sqlc.narg('q')::text, '\', '\\'), '%', '\%'), '_', '\_') || '%')
  AND (sqlc.narg('cursor_occurred_on')::date IS NULL
       OR (occurred_on, created_at, id) < (sqlc.narg('cursor_occurred_on')::date,
                                           sqlc.narg('cursor_created_at')::timestamptz,
                                           sqlc.narg('cursor_id')::uuid))
ORDER BY occurred_on DESC, created_at DESC, id DESC
LIMIT sqlc.arg('row_limit')::int;

-- name: RecentTransactions :many
SELECT * FROM transactions
WHERE user_id = @user_id
ORDER BY occurred_on DESC, created_at DESC, id DESC
LIMIT sqlc.arg('row_limit')::int;

-- name: ExportTransactions :many
-- CSV export: [from_date, to_date] inclusive, optional account, oldest first. Includes transfer legs
-- (category NULL for those).
SELECT t.id, t.occurred_on, t.type, t.amount_minor, t.currency, t.description, t.input_method,
       t.created_at,
       a.id   AS account_id,
       a.name AS account_name,
       c.key  AS category_key,
       c.name AS category_name
FROM transactions t
JOIN accounts a ON a.id = t.account_id AND a.user_id = t.user_id
LEFT JOIN categories c ON c.id = t.category_id
WHERE t.user_id = @user_id
  AND t.occurred_on >= @from_date::date
  AND t.occurred_on <= @to_date::date
  AND (sqlc.narg('account_id')::uuid IS NULL OR t.account_id = sqlc.narg('account_id')::uuid)
ORDER BY t.occurred_on, t.created_at, t.id;
